  "similarity_scores" TEXT NOT NULL CHECK ("similarity_scores" IS NULL OR json_valid("similarity_scores")),
  "baseline_pace" REAL,
  "baseline_hr" REAL,
  "baseline_drift" REAL,
  "baseline_pacing_stability" REAL,
  "pace_vs_baseline" REAL,
  "hr_vs_baseline" REAL,
  "drift_vs_baseline" REAL,
  "pacing_vs_baseline" REAL,
  "computed_at" TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  "expires_at" TEXT
);

CREATE TABLE "strava_webhook_logs" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,
  "event_id" TEXT,
  "event_type" TEXT NOT NULL,
  "object_type" TEXT NOT NULL,
  "object_id" TEXT NOT NULL,
  "athlete_id" TEXT NOT NULL,
  "subscription_id" INTEGER,
  "status" TEXT NOT NULL DEFAULT 'received',
  "error_message" TEXT,
  "raw_payload" TEXT,
  "received_at" TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  "processed_at" TEXT
);

CREATE TABLE "system_settings" (
  "key" TEXT PRIMARY KEY NOT NULL,
  "value" TEXT NOT NULL,
  "updated_at" TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

CREATE TABLE "training_plans_v2" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,
  "user_id" INTEGER NOT NULL,
  "goal_type" TEXT NOT NULL,
  "race_date" TEXT,
  "target_time" TEXT,
  "terrain_type" TEXT DEFAULT 'road',
  "days_per_week" INTEGER NOT NULL DEFAULT 4,
  "preferred_long_run_day" TEXT DEFAULT 'sunday',
  "preferred_days" TEXT CHECK ("preferred_days" IS NULL OR json_valid("preferred_days")),
  "allow_cross_training" INTEGER DEFAULT 1 CHECK ("allow_cross_training" IN (0,1)),
  "pace_based_workouts" INTEGER DEFAULT 1 CHECK ("pace_based_workouts" IN (0,1)),
  "status" TEXT DEFAULT 'draft',
  "total_weeks" INTEGER NOT NULL,
  "current_week" INTEGER DEFAULT 1,
  "coach_notes" TEXT,
  "generation_prompt" TEXT,
  "enrichment_status" TEXT DEFAULT 'pending',
  "enriched_weeks" INTEGER DEFAULT 0,
  "enrichment_error" TEXT,
  "created_at" TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  "updated_at" TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

CREATE TABLE "training_plans" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,
  "user_id" INTEGER NOT NULL,
  "weeks" INTEGER NOT NULL,
  "plan_data" TEXT NOT NULL CHECK ("plan_data" IS NULL OR json_valid("plan_data")),
  "created_at" TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

CREATE TABLE "user_campaigns" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,
  "user_id" INTEGER NOT NULL,
  "campaign" TEXT NOT NULL,
  "state" TEXT DEFAULT 'active',
  "current_step" INTEGER DEFAULT 1,
  "campaign_version" INTEGER NOT NULL DEFAULT 2,
  "experiment_variant" TEXT NOT NULL DEFAULT 'control',
  "is_holdout" INTEGER NOT NULL DEFAULT 0 CHECK ("is_holdout" IN (0,1)),
  "entered_at" TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  "exited_at" TEXT,
  "exit_reason" TEXT,
  "last_email_sent_at" TEXT,
  "updated_at" TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

CREATE TABLE "users" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,
  "email" TEXT UNIQUE,
  "password" TEXT,
  "first_name" TEXT,
  "last_name" TEXT,
  "username" TEXT UNIQUE,
  "strava_access_token" TEXT,
  "strava_refresh_token" TEXT,
  "strava_athlete_id" TEXT,
  "strava_connected" INTEGER DEFAULT 0 CHECK ("strava_connected" IN (0,1)),
  "strava_has_write_scope" INTEGER DEFAULT 0 CHECK ("strava_has_write_scope" IN (0,1)),
  "strava_branding_enabled" INTEGER DEFAULT 0 CHECK ("strava_branding_enabled" IN (0,1)),
  "strava_branding_template" TEXT DEFAULT '🏃 Runner Score: {score} | {insight}: Analyzed with RunAnalytics',
  "unit_preference" TEXT DEFAULT 'miles',
  "activity_view_mode" TEXT DEFAULT 'story',
  "is_admin" INTEGER DEFAULT 0 CHECK ("is_admin" IN (0,1)),
  "last_sync_at" TEXT,
  "sync_status" TEXT DEFAULT 'idle',
  "sync_progress" INTEGER DEFAULT 0,
  "sync_total" INTEGER DEFAULT 0,
  "sync_error" TEXT,
  "last_incremental_since" TEXT,
  "strava_webhook_paused_at" TEXT,
  "dormancy_notice_sent_at" TEXT,
  "needs_historical_backfill" INTEGER DEFAULT 0 CHECK ("needs_historical_backfill" IN (0,1)),
  "reset_token" TEXT,
  "reset_token_expiry" TEXT,
  "stripe_customer_id" TEXT,
  "stripe_subscription_id" TEXT,
  "subscription_status" TEXT DEFAULT 'active',
  "subscription_plan" TEXT DEFAULT 'free',
  "trial_ends_at" TEXT,
  "subscription_ends_at" TEXT,
  "monthly_insight_count" INTEGER DEFAULT 0,
  "insight_count_reset_at" TEXT,
  "coach_onboarding_completed" INTEGER DEFAULT 0 CHECK ("coach_onboarding_completed" IN (0,1)),
  "coach_goal" TEXT,
  "coach_race_date" TEXT,
  "coach_target_time" TEXT,
  "coach_days_available" TEXT CHECK ("coach_days_available" IS NULL OR json_valid("coach_days_available")),
  "coach_weekly_mileage_cap" REAL,
  "coach_tone" TEXT DEFAULT 'direct',
  "coach_notify_recap" INTEGER DEFAULT 1 CHECK ("coach_notify_recap" IN (0,1)),
  "coach_notify_weekly_summary" INTEGER DEFAULT 1 CHECK ("coach_notify_weekly_summary" IN (0,1)),
  "notify_post_run" INTEGER DEFAULT 1 CHECK ("notify_post_run" IN (0,1)),
  "post_run_email_frequency" TEXT DEFAULT 'every_run',
  "last_post_run_email_at" TEXT,
  "coach_quiet_hours_start" INTEGER,
  "coach_quiet_hours_end" INTEGER,
  "last_coach_sync_at" TEXT,
  "coach_enabled" INTEGER DEFAULT 1 CHECK ("coach_enabled" IN (0,1)),
  "coach_timezone" TEXT DEFAULT 'UTC',
  "coach_daily_briefing_enabled" INTEGER DEFAULT 1 CHECK ("coach_daily_briefing_enabled" IN (0,1)),
  "coach_daily_briefing_hour" INTEGER DEFAULT 7,
  "coach_weather_enabled" INTEGER DEFAULT 0 CHECK ("coach_weather_enabled" IN (0,1)),
  "coach_weather_location" TEXT CHECK ("coach_weather_location" IS NULL OR json_valid("coach_weather_location")),
  "coach_preferred_channel" TEXT DEFAULT 'email',
  "coach_snoozed_until" TEXT,
  "coach_daily_availability" TEXT,
  "coach_daily_availability_date" TEXT,
  "cached_recovery_state" TEXT CHECK ("cached_recovery_state" IS NULL OR json_valid("cached_recovery_state")),
  "recovery_calculated_at" TEXT,
  "activation_at" TEXT,
  "last_seen_at" TEXT,
  "marketing_opt_out" INTEGER DEFAULT 0 CHECK ("marketing_opt_out" IN (0,1)),
  "marketing_consent_status" TEXT DEFAULT 'unknown',
  "marketing_consented_at" TEXT,
  "marketing_unsubscribed_at" TEXT,
  "marketing_suppression_reason" TEXT,
  "marketing_consent_source" TEXT,
  "coach_questions_count_7d" INTEGER DEFAULT 0,
  "welcome_email_sent_at" TEXT,
  "onboarding_goal" TEXT,
  "onboarding_struggle" TEXT,
  "onboarding_days" TEXT,
  "onboarding_completed_at" TEXT,
  "premium_preview" TEXT CHECK ("premium_preview" IS NULL OR json_valid("premium_preview")),
  "premium_preview_created_at" TEXT,
  "created_at" TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

CREATE TABLE "workout_cache" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,
  "fingerprint" TEXT NOT NULL UNIQUE,
  "goal_type" TEXT NOT NULL,
  "workout_type" TEXT NOT NULL,
  "quality_level" INTEGER NOT NULL,
